export function vendorErrorIsRetryable(code: VendorErrorCode): boolean {
  const retryableCodes: VendorErrorCode[] = [
    VENDOR_ERROR.CODES.INTERNAL_ERROR,
    VENDOR_ERROR.CODES.SERVICE_UNAVAILABLE,
    VENDOR_ERROR.CODES.TIMEOUT,
    VENDOR_ERROR.CODES.RATE_LIMIT,
    VENDOR_ERROR.CODES.PAYMENT_FAILED,
    VENDOR_ERROR.CODES.SETTLEMENT_FAILED,
    VENDOR_ERROR.CODES.REPORT_GENERATION_FAILED,
    VENDOR_ERROR.CODES.REPORT_EXPORT_FAILED,
    VENDOR_ERROR.CODES.NOTIFICATION_FAILED,
  ];
  return retryableCodes.includes(code);
}

