    [VENDOR_ERROR.CODES.GENERAL_ERROR]: 500,
    [VENDOR_ERROR.CODES.VALIDATION_ERROR]: 400,
    [VENDOR_ERROR.CODES.NOT_FOUND]: 404,
    [VENDOR_ERROR.CODES.UNAUTHORIZED]: 401,
    [VENDOR_ERROR.CODES.FORBIDDEN]: 403,
    [VENDOR_ERROR.CODES.BAD_REQUEST]: 400,
